class AuthInterceptor(private val tokens: TokenStore) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        request.newBuilder()
            .header("Authorization", "Bearer ${tokens.access}")
            .build()
        return chain.proceed(request)
    }
}

import java.io.IOException
import java.net.SocketTimeoutException

class HttpException(val code: Int) : RuntimeException("HTTP $code")

fun toDomain(e: Throwable): String = when (e) {
    is HttpException -> when (e.code) {
        401 -> "Unauthorized"
        in 500..599 -> "Server"
        else -> "Client"
    }
    is IOException -> "Network"
    else -> "Unknown"
}

fun main() {
    val errors = listOf(SocketTimeoutException(), HttpException(503), HttpException(404), IllegalStateException())
    println(errors.joinToString { toDomain(it) })
}

